package net.neoforged.forgestuck.transformer.jar;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * Owner entries whose supported members were generated by {@code OwnerTableGenerator} (a test-side tool) from the
 * members that mods actually reference and that were verified by reflection to exist on the NeoForge 21.1.x target
 * with the same name and (owner-mapped) descriptor. File format ({@code forge-owner-members.txt}): a header line
 * {@code old/Owner -> new/Owner}, followed by member lines indented by two spaces ({@code name+legacyDescriptor},
 * {@code <init>()V} for constructors, {@code NAMEdescriptor} for fields). Lines starting with {@code #} are comments.
 */
final class GeneratedOwnerTable {
    static final String RESOURCE = "/net/neoforged/forgestuck/forge-owner-members.txt";

    private GeneratedOwnerTable() {}

    static List<ForgeOwnerMappings.Entry> entries() {
        try (InputStream in = GeneratedOwnerTable.class.getResourceAsStream(RESOURCE)) {
            return in == null ? List.of() : parse(new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)));
        } catch (IOException e) {
            throw new IllegalStateException("Cannot read " + RESOURCE, e);
        }
    }

    static List<ForgeOwnerMappings.Entry> parse(BufferedReader reader) throws IOException {
        List<ForgeOwnerMappings.Entry> out = new ArrayList<>();
        String oldOwner = null;
        String newOwner = null;
        Set<String> members = null;
        for (String line; (line = reader.readLine()) != null;) {
            if (line.isBlank() || line.startsWith("#")) continue;
            if (line.startsWith("  ")) {
                if (members != null) members.add(line.substring(2));
                continue;
            }
            if (oldOwner != null) out.add(new ForgeOwnerMappings.Entry(oldOwner, newOwner, Set.copyOf(members)));
            int arrow = line.indexOf(" -> ");
            oldOwner = line.substring(0, arrow).trim();
            newOwner = line.substring(arrow + 4).trim();
            members = new LinkedHashSet<>();
        }
        if (oldOwner != null) out.add(new ForgeOwnerMappings.Entry(oldOwner, newOwner, Set.copyOf(members)));
        return out;
    }
}
